const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Polygon([[
        [12.2, 51.3],
        [12.6, 51.3],
        [12.6, 51.1],
        [12.2, 51.1],
        [12.2, 51.3]
    ]]);

    const date1987 = { start: '1987-04-01', end: '1987-04-30' };
    const date2020 = { start: '2020-04-01', end: '2020-04-30' };

    // 2. Data Acquisition & Processing
    // Function to mask clouds in Landsat 5 C2 L2 data using QA_PIXEL band
    function maskL5(image) {
        const qa = image.select('QA_PIXEL');
        const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
        return image.updateMask(cloud.not());
    }

    // Function to mask clouds in Sentinel-2 SR Harmonized data using QA60 band
    function maskS2(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask);
    }

    // Period 1: April 1987 (Landsat 5)
    let collection1987 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(region)
        .filterDate(date1987.start, date1987.end);

    let waterPixels1987 = 0;
    if (collection1987.size().getInfo() > 0) {
        const image1987 = collection1987.map(maskL5).median();
        const ndwi1987 = image1987.normalizedDifference(['SR_B2', 'SR_B4']).rename('ndwi'); // Green, NIR
        const water1987 = ndwi1987.gt(0.1); // Threshold for water
        const maskedWater1987 = water1987.updateMask(water1987);

        const stats1987 = maskedWater1987.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: region,
            scale: 30, // Native scale for Landsat
            maxPixels: 1e9
        });
        const pixelCount = stats1987.get('ndwi').getInfo();
        if (pixelCount !== null) {
            waterPixels1987 = pixelCount * 30 * 30 / 1e6; // Area in sq km
        }
    } else {
        console.log("No images found for April 1987.");
        console.log("A"); // Assume increase if 1987 data is missing but 2020 is not
        return;
    }
    console.log(`1987 Water Surface Extent (sq km): ${waterPixels1987.toFixed(2)}`);

    // Period 2: April 2020 (Sentinel-2)
    let collection2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(date2020.start, date2020.end);

    let waterPixels2020 = 0;
    if (collection2020.size().getInfo() > 0) {
        const image2020 = collection2020.map(maskS2).median();
        const ndwi2020 = image2020.normalizedDifference(['B3', 'B8']).rename('ndwi'); // Green, NIR
        const water2020 = ndwi2020.gt(0.1); // Threshold for water
        const maskedWater2020 = water2020.updateMask(water2020);

        const stats2020 = maskedWater2020.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: region,
            scale: 30, // Use same scale for fair comparison
            maxPixels: 1e9
        });
        const pixelCount = stats2020.get('ndwi').getInfo();
        if (pixelCount !== null) {
            waterPixels2020 = pixelCount * 30 * 30 / 1e6; // Area in sq km
        }
    } else {
        console.log("No images found for April 2020.");
        console.log("C1");
        return;
    }
    console.log(`2020 Water Surface Extent (sq km): ${waterPixels2020.toFixed(2)}`);

    // 5. Validation & Final Answer
    if (waterPixels2020 > waterPixels1987) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
